import http from 'node:http';
import crypto from 'node:crypto';
import { readFileSync, writeFileSync, renameSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const DATA_FILE = process.env.DATA_FILE ?? path.join(path.dirname(fileURLToPath(import.meta.url)), 'books.json');
const PORT = process.env.PORT ?? 3000;

// --- storage ---------------------------------------------------------------

function loadBooks() {
  if (!existsSync(DATA_FILE)) return [];
  try {
    const books = JSON.parse(readFileSync(DATA_FILE, 'utf8'));
    return Array.isArray(books) ? books : [];
  } catch {
    return [];
  }
}

function saveBooks(books) {
  // write-then-rename so a crash mid-write can't corrupt the file
  const tmp = DATA_FILE + '.tmp';
  writeFileSync(tmp, JSON.stringify(books, null, 2) + '\n');
  renameSync(tmp, DATA_FILE);
}

// --- html ------------------------------------------------------------------

const esc = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const page = (title, body) => `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  :root { color-scheme: light dark; }
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; }
  h1 { font-size: 1.5rem; }
  h2 { font-size: 1.1rem; margin-top: 2rem; border-bottom: 1px solid #8884; padding-bottom: .3rem; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; align-items: baseline; gap: .6rem; padding: .35rem 0; }
  ul.books .author { opacity: .7; }
  ul.books form { margin-left: auto; }
  .muted { opacity: .6; }
  form.add { display: grid; gap: .5rem; margin-top: .5rem; }
  input, textarea { font: inherit; padding: .4rem; width: 100%; box-sizing: border-box; }
  button { font: inherit; padding: .3rem .8rem; cursor: pointer; }
  a { color: inherit; }
  .notes { white-space: pre-wrap; background: #8881; padding: 1rem; border-radius: .5rem; }
  .back { display: inline-block; margin-bottom: 1rem; }
</style>
</head>
<body>
${body}
</body>
</html>`;

function bookItem(book) {
  const finishBtn = book.finished
    ? ''
    : `<form method="post" action="/book/${book.id}/finish"><button>Finished it</button></form>`;
  return `<li>
    <a href="/book/${book.id}">${esc(book.title)}</a>
    <span class="author">${esc(book.author)}</span>
    ${finishBtn}
  </li>`;
}

function homePage(books) {
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);
  return page('My books', `
  <h1>My books</h1>

  <h2>Currently reading</h2>
  ${reading.length ? `<ul class="books">${reading.map(bookItem).join('')}</ul>` : '<p class="muted">Nothing at the moment.</p>'}

  <h2>Finished</h2>
  ${finished.length ? `<ul class="books">${finished.map(bookItem).join('')}</ul>` : '<p class="muted">Nothing finished yet.</p>'}

  <h2>Add a book</h2>
  <form class="add" method="post" action="/books">
    <input name="title" placeholder="Title" required>
    <input name="author" placeholder="Author" required>
    <textarea name="notes" placeholder="Notes (optional)" rows="4"></textarea>
    <button>Add book</button>
  </form>`);
}

function bookPage(book) {
  return page(book.title, `
  <a class="back" href="/">&larr; All books</a>
  <h1>${esc(book.title)}</h1>
  <p class="author">by ${esc(book.author)} &middot; ${book.finished ? 'finished' : 'currently reading'}</p>
  ${book.finished ? '' : `<form method="post" action="/book/${book.id}/finish"><button>Finished it</button></form>`}
  <h2>Notes</h2>
  ${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : '<p class="muted">No notes yet.</p>'}`);
}

// --- server ----------------------------------------------------------------

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
      if (body.length > 1e6) reject(new Error('body too large'));
    });
    req.on('end', () => resolve(new URLSearchParams(body)));
    req.on('error', reject);
  });
}

const send = (res, status, html) =>
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' }).end(html);
const redirect = (res, location) => res.writeHead(303, { location }).end();

export const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    const books = loadBooks();

    if (req.method === 'GET' && url.pathname === '/') {
      return send(res, 200, homePage(books));
    }

    const bookMatch = url.pathname.match(/^\/book\/([\w-]+)$/);
    if (req.method === 'GET' && bookMatch) {
      const book = books.find((b) => b.id === bookMatch[1]);
      if (!book) return send(res, 404, page('Not found', '<h1>Book not found</h1><p><a href="/">Back to all books</a></p>'));
      return send(res, 200, bookPage(book));
    }

    if (req.method === 'POST' && url.pathname === '/books') {
      const form = await readForm(req);
      const title = (form.get('title') ?? '').trim();
      const author = (form.get('author') ?? '').trim();
      if (!title || !author) return send(res, 400, page('Error', '<h1>Title and author are required</h1><p><a href="/">Back</a></p>'));
      const book = {
        id: crypto.randomUUID(),
        title,
        author,
        notes: (form.get('notes') ?? '').trim(),
        finished: false,
        addedAt: new Date().toISOString(),
      };
      saveBooks([...books, book]);
      return redirect(res, '/');
    }

    const finishMatch = url.pathname.match(/^\/book\/([\w-]+)\/finish$/);
    if (req.method === 'POST' && finishMatch) {
      const book = books.find((b) => b.id === finishMatch[1]);
      if (!book) return send(res, 404, page('Not found', '<h1>Book not found</h1><p><a href="/">Back to all books</a></p>'));
      book.finished = true;
      book.finishedAt = new Date().toISOString();
      saveBooks(books);
      return redirect(res, req.headers.referer?.endsWith(`/book/${book.id}`) ? `/book/${book.id}` : '/');
    }

    send(res, 404, page('Not found', '<h1>Not found</h1><p><a href="/">Back to all books</a></p>'));
  } catch (err) {
    console.error(err);
    send(res, 500, page('Error', '<h1>Something went wrong</h1><p><a href="/">Back to all books</a></p>'));
  }
});

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  server.listen(PORT, () => console.log(`Book tracker running at http://localhost:${PORT}`));
}

